import type {FC} from 'react';
import React from 'react';

import {Folders} from '@gravity-ui/icons';

import type {EntityIconProps} from '../EntityIcon';
import {EntityIcon} from '../EntityIcon';

export type ProjectIconProps = {projectId?: number | string} & Omit<
    EntityIconProps,
    'data' | 'id' | 'alpha'
>;

export const ProjectIcon: FC<ProjectIconProps> = ({projectId, ...props}) => (
    <EntityIcon data={Folders} id={projectId} type="project" {...props} />
);
